from taf.ul.ettf.msg_capture.expectation_builders import TaggedMatcher, Expected
from taf.ul.ettf.ta_matchers.matchers import MatchingResult, Mismatch
from taf.ul.ettf.utils import exception_causes
from taf.ul.ettf.utils.exception import LibraryError


UNEXISTING_PACKET = None
UNEXISTING_RESULT = None

UNEXPECTED_PACKET_MISMATCH = Mismatch(msg='Packet should not be matched',
                                      expected='to be missing',
                                      actual='present')


def _check_tags(m_set, m_test):
    return all(m in m_set for m in m_test)


def get_matchers_with_tags(matchers, tags):
    filtered_matchers = []
    for matcher in matchers:
        if not isinstance(matcher, TaggedMatcher) and _check_tags(Expected.tags, tags):
            filtered_matchers.append(matcher)
            continue
        elif not isinstance(matcher, TaggedMatcher):
            continue
        elif _check_tags(matcher.tags, tags):
            filtered_matchers.append(matcher.matcher)
    return filtered_matchers


def setup_registry(condition, registry):
    registry.clear()
    registry.set_container_type(condition)
    condition.append_callback(registry.log_callback)


class PartialMatch(MatchingResult):
    def __init__(self):
        super(PartialMatch, self).__init__(mismatches=[])

    def __bool__(self):
        return False

    __nonzero__ = __bool__


class WrongOrderError(LibraryError):
    def __init__(self, msg):
        super(WrongOrderError, self).__init__(exception_causes.CONDITION_NOT_MET, msg)
